// Decide today's touches: step 1 for approved (queued) prospects, step 2 at
// day 3, step 3 (breakup) at day 8, mark lost 3 days after the breakup.
const DAY = 86400000;
const now = Date.now();

const hist = {}; // prospect_id -> { firstAt, lastAt, maxStep }
for (const i of $('Get Outbound History').all()) {
  const c = i.json;
  if (!c || !c.prospect_id) continue;
  const t = new Date(c.sent_at).getTime();
  const h = hist[c.prospect_id] || { firstAt: t, lastAt: t, maxStep: 0 };
  h.firstAt = Math.min(h.firstAt, t);
  h.lastAt = Math.max(h.lastAt, t);
  h.maxStep = Math.max(h.maxStep, c.sequence_step || 1);
  hist[c.prospect_id] = h;
}

const out = [];

for (const i of $('Get Queued').all()) {
  const p = i.json;
  if (!p || !p.id) continue;
  // 45-day re-contact lockout
  if (p.last_contacted && now - new Date(p.last_contacted).getTime() < 45 * DAY) continue;
  out.push({ json: { action: 'send', step: 1, angle: 'opener', ...p } });
}

for (const i of $('Get In Sequence').all()) {
  const p = i.json;
  if (!p || !p.id) continue;
  const h = hist[p.id];
  if (!h) continue;
  if (h.maxStep >= 3) {
    if (now - h.lastAt >= 3 * DAY) out.push({ json: { action: 'mark_lost', ...p } });
  } else if (h.maxStep === 2) {
    if (now - h.firstAt >= 8 * DAY) out.push({ json: { action: 'send', step: 3, angle: 'breakup', ...p } });
  } else if (h.maxStep === 1) {
    if (now - h.firstAt >= 3 * DAY) out.push({ json: { action: 'send', step: 2, angle: 'follow_up', ...p } });
  }
}

return out;

// Build the OpenRouter request for this touch: evidence-based, one question,
// loss frame not feature pitch.
const p = $input.first().json;
const sig = p.signals || {};
const evidence = [];
if (sig.detected && sig.detected.ads) evidence.push('they are running paid ads (' + sig.detected.ads.join(', ') + ')');
if (!sig.detected || !sig.detected.chat) evidence.push('no chat or intake widget on the site');
if (!sig.detected || !sig.detected.booking) evidence.push('no online booking tool');
if (sig.has_contact_form) evidence.push('intake goes to a plain contact form');
if (sig.answer_language) evidence.push('site promises "we answer 24/7"-type availability');
if (sig.review_count) evidence.push(sig.review_count + ' Google reviews at ' + sig.rating);

const EXAMPLES = {
  law_firm: 'Noticed [Firm] is running ads but the intake page goes to a form. Curious - of the calls that come in after 6pm, roughly how many end up signing?',
  medical: 'Quick one - when someone calls to book and gets voicemail at lunch, does anyone track how many of those call back?',
  home_services: 'When your techs are on a job and the phone rings, where does that call go? Trying to figure out if that is a real problem for shops your size or if I am overthinking it.',
};

const ANGLES = {
  opener: 'First touch. Reference one specific thing we observed on their website and ask ONE question about leads they might be losing.',
  follow_up: 'Second touch, 3 days later, they did not reply. Different angle from a generic bump - a new observation or a sharper version of the question. Do NOT say "just following up". Still exactly one question.',
  breakup: 'Third and final touch, day 8. Short breakup note - ask if you should close the file. Two sentences max.',
};

const system = 'You write cold outreach emails for Sanaku, a one-person AI automation agency. Rules: under 400 characters. Exactly one question. Never pitch features or mention AI/automation tools. The frame is money lost to missed leads, not what we sell. Sound like a busy person typed it - lowercase-ish, direct, zero fluff. Absolutely never write "I hope this email finds you well" or any variant. Output ONLY the email body, no subject, no signature, no quotes.';

const user = 'Business: ' + p.company_name + ' (' + p.vertical + ')\n' +
  'Decision maker: ' + (p.contact_name || 'unknown') + '\n' +
  'What we found on their site: ' + (evidence.join('; ') || 'nothing notable') + '\n' +
  'Touch type: ' + ANGLES[p.angle] + '\n' +
  'Style reference for this vertical (do not copy verbatim): ' + EXAMPLES[p.vertical];

return [{ json: { ...p, orBody: {
  model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
  messages: [ { role: 'system', content: system }, { role: 'user', content: user } ],
  max_tokens: 220,
  temperature: 0.8,
} } }];

// Validate the LLM output; fall back to the hand-written bank if it broke a rule.
const p = $('Build Prompt').first().json;
const resp = $input.first().json || {};
let body = '';
try { body = String(resp.choices[0].message.content || '').trim(); } catch (e) { body = ''; }
body = body.replace(/^["']|["']$/g, '').trim();

const FALLBACK = {
  law_firm: {
    1: 'Noticed ' + p.company_name + ' is running ads but the intake page goes to a form. Curious - of the calls that come in after 6pm, roughly how many end up signing?',
    2: 'One more thought - when an accident victim calls three firms in a row, whoever answers first usually wins the case. Do you know how fast your intake responds after hours?',
    3: 'Have not heard back so I will assume missed intake calls are not a priority right now - should I close the file?',
  },
  medical: {
    1: 'Quick one - when someone calls to book and gets voicemail at lunch, does anyone track how many of those call back?',
    2: 'Was thinking about your front desk - what happens to booking calls that come in after close? Do they land anywhere?',
    3: 'No worries if the timing is off - should I close the file on this?',
  },
  home_services: {
    1: 'When your techs are on a job and the phone rings, where does that call go? Trying to figure out if that is a real problem for shops your size or if I am overthinking it.',
    2: 'Curious what an emergency call that hits voicemail is worth to you - the ones that call the next shop when nobody picks up.',
    3: 'Guessing missed calls are not a burning issue right now - want me to close the file?',
  },
};

const invalid = !body || body.length > 400 || !body.includes('?') || /hope this (e-?mail )?finds you/i.test(body);
if (invalid) body = FALLBACK[p.vertical][p.step];

const first = (p.contact_name || '').split(' ')[0];
const greeting = first ? first + ' - ' : '';
const footer = '\n\n-\nIsmail | Sanaku\n' + ($env.SANAKU_MAILING_ADDRESS || '') + "\nIf you'd rather not hear from me, reply 'no thanks' and I'll close the file for good.";

const SUBJECTS = { 1: 'quick question about ' + p.company_name, 2: 're: quick question about ' + p.company_name, 3: 'closing the file?' };

return [{ json: {
  ...p,
  email_subject: SUBJECTS[p.step],
  email_body: greeting + body + footer,
  message_logged: body,
  used_fallback: invalid,
} }];

// Summarize what this run did (reads the plan, not the loop debris).
const planned = $('Plan Touches').all().map((i) => i.json);
const sends = planned.filter((p) => p.action === 'send');
const lost = planned.filter((p) => p.action === 'mark_lost');
const byStep = { 1: 0, 2: 0, 3: 0 };
for (const s of sends) byStep[s.step]++;
const html = '<p>Sanaku outreach run complete.</p><ul>' +
  '<li>Openers sent: ' + byStep[1] + '</li>' +
  '<li>Day-3 follow-ups: ' + byStep[2] + '</li>' +
  '<li>Day-8 breakups: ' + byStep[3] + '</li>' +
  '<li>Marked lost: ' + lost.length + '</li></ul>' +
  (sends.length ? '<p>' + sends.map((s) => s.company_name + ' (step ' + s.step + ')').join('<br>') + '</p>' : '');
return [{ json: { html, subject: 'Sanaku outreach: ' + sends.length + ' sent, ' + lost.length + ' closed' } }];
